caught.content:
- name: Set up the pinned PHP and Composer
  if: contains(fromJSON('["php","blade"]'), matrix.pack)
  uses: ./.github/actions/php

- name: Smoke the installed package
  run: |
    node --input-type=module --eval '
      import { existsSync } from "node:fs";
      import { join } from "node:path";
      const root = process.argv[1];
      for (const host of ["claude", "codex", "cursor"]) {
        if (!existsSync(join(root, "dist", "hosts", host, `${host}-hook.js`))) process.exit(1);
      }
    ' "$installed"

- run: |
    node --input-type=module --eval '
      const legs = [{ pack: "python", tool: "ruff" }, { pack: "sql", tool: "sqlfluff" }];
      console.log(JSON.stringify(legs));
    ' > legs.json

strategy:
  matrix:
    pack: ${{ fromJSON('["python", "sql", "vue"]') }}

- name: Set up PHP
  if: startsWith(matrix.pack, 'php') || contains(matrix.pack, 'blade')
  uses: ./.github/actions/php

passed.content:
- name: Smoke the installed package
  run: |
    node --input-type=module - "$installed" <<'EOF'
    const { ENTRY_POINTS } = await import(pathToFileURL(join(root, "dist", "engine", "package-root.js")).href);
    const missing = Object.values(ENTRY_POINTS).filter((path) => !existsSync(join(root, path)));
    EOF

strategy:
  matrix:
    include: ${{ fromJSON(needs.plan.outputs.legs) }}
name: ${{ matrix.pack }}/${{ matrix.tool }}

- env:
    PACK: ${{ inputs.pack }}
  run: |
    case "$PACK" in
      ''|*[!a-z0-9._-]*) echo "::error::'$PACK' is not a pack id"; exit 1 ;;
    esac
